import heapq

def match(orders):
    trades = []
    buy_heap = []   # entries: (-price, seq, id)
    sell_heap = []  # entries: (price, seq, id)
    book = {}       # id -> dict with side, price, qty, seq
    seq_counter = 0

    for order in orders:
        seq_counter += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            if oid in book:
                del book[oid]
            continue

        oid = order[1]
        side = order[2]
        if typ == 'market':
            price = None
            qty = order[3]
        else:
            price = order[3]
            qty = order[4]

        remaining = qty

        if side == 'buy':
            heap = sell_heap
        else:
            heap = buy_heap

        while remaining > 0 and heap:
            if side == 'buy':
                top_price, top_seq, top_id = heap[0]
            else:
                neg_price, top_seq, top_id = heap[0]
                top_price = -neg_price

            if top_id not in book:
                heapq.heappop(heap)
                continue

            resting = book[top_id]
            if resting['qty'] <= 0:
                heapq.heappop(heap)
                if top_id in book:
                    del book[top_id]
                continue

            resting_price = resting['price']

            if typ != 'market':
                if side == 'buy' and resting_price > price:
                    break
                if side == 'sell' and resting_price < price:
                    break

            trade_qty = min(remaining, resting['qty'])
            if side == 'buy':
                trades.append([oid, top_id, resting_price, trade_qty])
            else:
                trades.append([top_id, oid, resting_price, trade_qty])

            remaining -= trade_qty
            resting['qty'] -= trade_qty

            if resting['qty'] == 0:
                heapq.heappop(heap)
                del book[top_id]
            # else: partially filled resting order keeps its place; do not pop

        if typ == 'limit' and remaining > 0:
            book[oid] = {'side': side, 'price': price, 'qty': remaining, 'seq': seq_counter}
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))

    return trades

